Vue.component("tema",{props:["type","url","name","date"],template:'\n    <div class="rp-list">\n        <a class="rp-element" :href="url" :title="\'Ir al tema «\' + name + \'»\'">\n            <div class="rp-icon">\n                <template v-if="type === \'abierto\'">\n                    <i class="fas fa-lock-open"></i>\n                </template>\n                <template v-else-if="type === \'cerrado\'">\n                    <i class="fas fa-lock"></i>\n                </template>\n                <template v-else-if="type === \'abandonado\'">\n                    <i class="fas fa-times"></i>\n                </template>\n            </div>\n            <div class="rp-content">\n                <div class="rp-name">\n                    <span>{{ name }}</span>\n                    <small>\n                        {{ date }} - <slot></slot>\n                    </small>\n                </div>\n            </div>\n        </a>\n    </div>\n    '}),Vue.component("relacion",{props:["id","name","img","color"],data:()=>({profileName:forumConfig.profileOptions.profileName||"perfil"}),computed:{relaClass(){return"rela-list usergroup-"+this.color.toLowerCase()},relaType(){return void 0!==this.id}},template:'\n    <div :class="relaClass">\n        <template v-if="relaType">\n            <a class="rela-element" :href="\'/u\' + id" :title="\'Ir al \' + profileName + \' de «\' + name + \'»\'">\n                <div class="rela-image" :style="\'background-image: url(\' + img + \')\'"></div>\n                <div class="rela-content">\n                    <div class="rela-title">\n                        <h4>{{ name }}</h4>\n                    </div>\n                    <div class="small-text is-content">\n                        <slot></slot>\n                    </div>\n                </div>\n            </a>\n        </template>\n        <template v-else>\n            <a class="rela-element">\n                <div class="rela-image" :style="\'background-image: url(\' + img + \')\'"></div>\n                <div class="rela-content">\n                    <div class="rela-title">\n                        <h4>{{ name }}</h4>\n                    </div>\n                    <div class="small-text is-content">\n                        <slot></slot>\n                    </div>\n                </div>\n            </a>\n        </template>\n    </div>\n    '});